//! Lab and range host safety (external audit Wave 3, lab PR 211: NN-AUD-409
//! LAB-019, NN-AUD-412 LAB-022, NN-AUD-415 LAB-025, NN-AUD-417 LAB-027).
//! The lab and range scripts do not harm the host they run on: the lab
//! talks to a guest only when it presents the guest's own ssh host key
//! (generated by `nn-lab.sh up` and injected, or recorded once from the
//! guest's own port), the open-sensor check refuses a host that is not a
//! lab guest and puts `~/.aws` back as it found it, the range teardown says
//! what it does and deletes no disk outside a VM's folder, and the range
//! bootstrap refuses a tree it cannot vouch for and records what it
//! installed. Offline: committed files, `bash`, OpenSSH's client tools,
//! `git`, `python3 -I` and stubs; no guest, nothing privileged, nothing
//! written outside the target and temporary directories.

use std::fs;
use std::io::{BufRead, BufReader};
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Output, Stdio};

const NN_LAB: &str = "deploy/lab/nn-lab.sh";
const OPEN_SENSOR: &str = "deploy/lab/open-sensor/open-sensor-check.sh";
const TEARDOWN: &str = "docs/adversarial/scripts/07_teardown.sh";
const BOOTSTRAP: &str = "deploy/adversarial/bootstrap-target-prod.sh";

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("xtask lives one level below the repository root")
        .to_path_buf()
}

fn read(rel: &str) -> String {
    let path = repo_root().join(rel);
    fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

/// The `# >>> name` … `# <<< name` block of a script.
fn block(rel: &str, name: &str) -> String {
    let text = read(rel);
    let start = text
        .find(&format!("# >>> {name}"))
        .unwrap_or_else(|| panic!("{rel}: no `# >>> {name}` block"));
    let end_marker = format!("# <<< {name}");
    let end = text[start..]
        .find(&end_marker)
        .map(|i| start + i + end_marker.len())
        .unwrap_or_else(|| panic!("{rel}: `{name}` block not closed"));
    text[start..end].to_string()
}

/// A fresh directory under the target dir (inside the repository).
fn case_dir(name: &str) -> PathBuf {
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join("lab-host-safety")
        .join(name);
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).unwrap();
    dir
}

/// A fresh directory outside the repository (its parents carry the
/// repository's own `.cargo/config.toml`, which the range check refuses).
/// Removed when dropped, a failing test included.
struct OutsideDir(PathBuf);
impl Drop for OutsideDir {
    fn drop(&mut self) {
        // modes a test case may have left
        let _ = Command::new("chmod")
            .arg("-R")
            .arg("u+rwx")
            .arg(&self.0)
            .status();
        let _ = fs::remove_dir_all(&self.0);
    }
}
fn outside_dir(name: &str) -> OutsideDir {
    let dir =
        std::env::temp_dir().join(format!("nn-lab-host-safety-{}-{name}", std::process::id()));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).unwrap();
    OutsideDir(dir)
}

fn write_exec(path: &Path, body: &str) {
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(path, body).unwrap();
    fs::set_permissions(path, fs::Permissions::from_mode(0o755)).unwrap();
}

/// `bash -c "<script>" bash ARGS…` in the repository, the test's
/// environment plus `env`.
fn bash(script: &str, args: &[&str], env: &[(&str, &str)]) -> Output {
    let mut cmd = Command::new("bash");
    cmd.arg("-c")
        .arg(script)
        .arg("bash")
        .args(args)
        .current_dir(repo_root())
        .stdin(Stdio::null());
    for (k, v) in env {
        cmd.env(k, v);
    }
    cmd.output().expect("bash runs")
}

fn text(out: &Output) -> String {
    format!(
        "{}{}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    )
}

fn have(tool: &str) -> bool {
    Command::new("bash")
        .arg("-c")
        .arg(format!("command -v {tool}"))
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

/// A process that only waits: a pid for a pid file (never this test's own,
/// which `nn-lab.sh down` would end up killing).
struct Sleeper(Child);
impl Sleeper {
    fn new() -> Sleeper {
        Sleeper(Command::new("sleep").arg("120").spawn().unwrap())
    }
    fn pid(&self) -> String {
        self.0.id().to_string()
    }
}
impl Drop for Sleeper {
    fn drop(&mut self) {
        let _ = self.0.kill();
        let _ = self.0.wait();
    }
}

/// A TCP listener on 127.0.0.1 (a free port), as a separate process.
struct Listener {
    child: Child,
    port: String,
}
impl Listener {
    fn new() -> Listener {
        let mut child = Command::new("python3")
            .arg("-I")
            .arg("-c")
            .arg(
                "import socket,time\n\
                 s=socket.socket(); s.bind(('127.0.0.1',0)); s.listen()\n\
                 print(s.getsockname()[1], flush=True)\n\
                 time.sleep(120)\n",
            )
            .stdout(Stdio::piped())
            .spawn()
            .expect("python3 runs");
        let mut line = String::new();
        BufReader::new(child.stdout.take().unwrap())
            .read_line(&mut line)
            .unwrap();
        Listener {
            port: line.trim().to_string(),
            child,
        }
    }
    fn pid(&self) -> String {
        self.child.id().to_string()
    }
}
impl Drop for Listener {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

/// An ed25519 key pair made by ssh-keygen: (private file, "ssh-ed25519 B64").
fn keypair(dir: &Path, name: &str) -> (PathBuf, String) {
    let key = dir.join(name);
    let out = Command::new("ssh-keygen")
        .args(["-q", "-t", "ed25519", "-N", "", "-C", "test", "-f"])
        .arg(&key)
        .stdin(Stdio::null())
        .output()
        .expect("ssh-keygen runs");
    assert!(out.status.success(), "{}", text(&out));
    let pub_line = fs::read_to_string(key.with_extension("pub")).unwrap();
    let two: Vec<&str> = pub_line.split_whitespace().take(2).collect();
    (key, two.join(" "))
}

fn fn_prelude() -> &'static str {
    "set -euo pipefail\nlog() { printf 'nn-lab: %s\\n' \"$*\" >&2; }\n\
     die() { log \"ERROR: $*\"; exit 1; }\n"
}

// ── LAB-025: the guest's host key (nn-lab.sh) ───────────────────────────

fn templates() -> Vec<PathBuf> {
    let dir = repo_root().join("deploy/lab");
    let mut t: Vec<PathBuf> = fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| n.starts_with("user-data") && n.ends_with(".tmpl"))
        })
        .collect();
    t.sort();
    assert!(t.len() >= 4, "{t:?}");
    t
}

/// The private key cloud-init would write: the `ed25519_private: |` block.
fn rendered_private_key(user_data: &str) -> String {
    let mut lines = user_data.lines();
    lines
        .by_ref()
        .find(|l| l.trim_end() == "  ed25519_private: |")
        .expect("an ed25519_private block");
    let mut key = String::new();
    for l in lines {
        match l.strip_prefix("    ") {
            Some(k) => {
                key.push_str(k);
                key.push('\n');
            }
            None => break,
        }
    }
    key
}

/// The guests got whatever host key cloud-init generated, and the lab
/// took any key. Every template now carries an `ssh_keys:` entry that
/// `render_user_data` fills with a key generated on the host for each
/// instance: the private half only in the user-data (0600), its public half
/// next to it; a template without the entry is refused.
#[test]
fn every_guest_template_carries_a_host_key_made_on_the_host() {
    let render = block(NN_LAB, "render-user-data");
    let dir = case_dir("render");
    keypair(&dir, "key");
    for t in templates() {
        let tmpl = fs::read_to_string(&t).unwrap();
        let name = t.display();
        assert!(tmpl.contains("\nssh_deletekeys: true\n"), "{name}");
        assert!(tmpl.contains("\nssh_keys:\n  ed25519_private: |\n    __NN_LAB_HOST_KEY__\n  ed25519_public: __NN_LAB_HOST_KEY_PUB__\n"), "{name}");
        let mut seen = Vec::new();
        for round in 0..2 {
            let ud = dir.join("user-data");
            let script = format!(
                "{}{render}\nKEY={key}; USER_DATA_TMPL={t}; LOCKDOWN=\nrender_user_data {ud}\n",
                fn_prelude(),
                key = dir.join("key").display(),
                t = t.display(),
                ud = ud.display(),
            );
            let out = bash(&script, &[], &[]);
            assert!(out.status.success(), "{name}: {}", text(&out));
            let rendered = fs::read_to_string(&ud).unwrap();
            assert_eq!(
                fs::metadata(&ud).unwrap().permissions().mode() & 0o777,
                0o600,
                "{name}"
            );
            let pub_line = fs::read_to_string(dir.join("ssh_host_ed25519_key.pub")).unwrap();
            let public: Vec<&str> = pub_line.split_whitespace().take(2).collect();
            assert!(
                rendered.contains(&format!("  ed25519_public: {}", public.join(" "))),
                "{name}"
            );
            // the private half in the user-data is the public half's
            let private = dir.join("private");
            fs::write(&private, rendered_private_key(&rendered)).unwrap();
            fs::set_permissions(&private, fs::Permissions::from_mode(0o600)).unwrap();
            let derived = Command::new("ssh-keygen")
                .arg("-y")
                .arg("-f")
                .arg(&private)
                .output()
                .unwrap();
            assert!(derived.status.success(), "{name}: {}", text(&derived));
            let derived = String::from_utf8_lossy(&derived.stdout);
            let derived: Vec<&str> = derived.split_whitespace().take(2).collect();
            assert_eq!(derived, public, "{name} (round {round})");
            seen.push(public.join(" "));
            fs::remove_file(&private).unwrap();
            // no copy of the private half left next to the user-data
            for e in fs::read_dir(&dir).unwrap() {
                let n = e.unwrap().file_name().into_string().unwrap();
                assert!(!n.starts_with(".host-key"), "{name}: {n} left");
            }
        }
        assert_ne!(seen[0], seen[1], "{name}: a new instance, a new key");
    }
    // a template without the ssh_keys entry
    let bare = dir.join("bare.tmpl");
    fs::write(
        &bare,
        "#cloud-config\nusers:\n  - ssh_authorized_keys: [__SSH_PUBKEY__]\nruncmd:\n  - grubby --args=\"lsm=bpf__NN_LAB_KARGS__\"\n",
    )
    .unwrap();
    let script = format!(
        "{}{render}\nKEY={key}; USER_DATA_TMPL={bare}; LOCKDOWN=\nrender_user_data {out}\n",
        fn_prelude(),
        key = dir.join("key").display(),
        bare = bare.display(),
        out = dir.join("bare-out").display(),
    );
    let out = bash(&script, &[], &[]);
    assert!(!out.status.success());
    assert!(
        text(&out).contains("has no ssh_keys: entry"),
        "{}",
        text(&out)
    );
}

/// The guest's ssh options, in a lab directory whose path has a space.
fn ssh_options(lab: &Path) -> String {
    format!(
        "{}LAB_DIR={lab:?}; ROOT_LAB_DIR=$LAB_DIR; KEY=\"$LAB_DIR/id_ed25519\"; GUEST_NAME=ubuntu2404; SSH_PORT=2322\n{}\n",
        fn_prelude(),
        block(NN_LAB, "ssh-options"),
        lab = lab.display().to_string(),
    )
}

/// `ssh -G` over options: the effective client configuration.
fn effective(opts: &[String]) -> String {
    let out = Command::new("ssh")
        .arg("-G")
        .args(opts)
        .arg("nn@127.0.0.1")
        .stdin(Stdio::null())
        .output()
        .expect("ssh runs");
    assert!(out.status.success(), "{}", text(&out));
    String::from_utf8_lossy(&out.stdout).into_owned()
}

fn assert_strict(cfg: &str, lab: &Path) {
    let kh = lab.join("known_hosts");
    for want in [
        "stricthostkeychecking true".to_string(),
        format!("userknownhostsfile {}", kh.display()),
        "globalknownhostsfile /dev/null".to_string(),
        "hostkeyalias nn-lab-ubuntu2404".to_string(),
        "hostkeyalgorithms ssh-ed25519".to_string(),
        "identitiesonly yes".to_string(),
        "updatehostkeys false".to_string(),
        "port 2322".to_string(),
    ] {
        assert!(cfg.lines().any(|l| l == want), "no `{want}` in:\n{cfg}");
    }
}

/// Host key checking was off for every guest connection (ssh, rsync, scp),
/// and `-e "ssh ${SSH_OPTS[*]}"` broke on a space in a path. ssh, and rsync
/// through its -e string, now check the guest's own known_hosts strictly,
/// under the guest's alias, ed25519 only, offering the lab key only.
#[test]
fn every_guest_connection_checks_the_guests_host_key() {
    let dir = case_dir("ssh-options");
    let lab = dir.join("lab dir");
    fs::create_dir_all(&lab).unwrap();
    keypair(&lab, "id_ed25519");
    let script = format!(
        "{}printf '%s\\n' \"${{SSH_OPTS[@]}}\" > {opts:?}\nprintf '%s\\n' \"$RSYNC_RSH\" > {rsh:?}\n",
        ssh_options(&lab),
        opts = dir.join("opts").display().to_string(),
        rsh = dir.join("rsh").display().to_string(),
    );
    let out = bash(&script, &[], &[]);
    assert!(out.status.success(), "{}", text(&out));
    let opts: Vec<String> = fs::read_to_string(dir.join("opts"))
        .unwrap()
        .lines()
        .map(str::to_string)
        .collect();
    assert!(!opts.iter().any(|o| o.contains("StrictHostKeyChecking=no")));
    assert_strict(&effective(&opts), &lab);
    // rsync hands the same arguments to ssh (a stub that records them)
    if !have("rsync") {
        eprintln!("SKIP rsync part: no rsync on this host");
        return;
    }
    let bin = dir.join("bin");
    write_exec(
        &bin.join("ssh"),
        "#!/bin/bash\nprintf '%s\\n' \"$@\" > \"$ARGLOG\"\nexit 12\n",
    );
    fs::write(dir.join("payload"), "x\n").unwrap();
    let script = format!(
        "{}rsync -a -e \"$RSYNC_RSH\" {payload:?} nn@127.0.0.1:/tmp/nn-x || true\n",
        ssh_options(&lab),
        payload = dir.join("payload").display().to_string(),
    );
    let path = format!("{}:{}", bin.display(), std::env::var("PATH").unwrap());
    let arglog = dir.join("args");
    let out = bash(
        &script,
        &[],
        &[("PATH", &path), ("ARGLOG", arglog.to_str().unwrap())],
    );
    let got = fs::read_to_string(&arglog).unwrap_or_else(|_| panic!("{}", text(&out)));
    let got: Vec<String> = got
        .lines()
        .take_while(|a| *a != "-l" && *a != "nn@127.0.0.1")
        .map(str::to_string)
        .collect();
    assert_eq!(got, opts, "rsync -e split the options");
}

/// A lab directory with a quote in its path cannot be quoted for rsync:
/// refused before anything runs.
#[test]
fn nn_lab_refuses_a_lab_directory_with_a_quote() {
    let dir = case_dir("quote");
    let lab = dir.join("it's");
    let out = Command::new("bash")
        .arg(repo_root().join(NN_LAB))
        .arg("status")
        .env("HOME", &dir)
        .env("NN_LAB_DIR", &lab)
        .env_remove("NN_LAB_DISTRO")
        .env_remove("NN_LAB_ACCEL")
        .env_remove("NN_LAB_LOCKDOWN")
        .output()
        .unwrap();
    assert_eq!(out.status.code(), Some(2), "{}", text(&out));
    assert!(text(&out).contains("must not contain a quote"));
}

/// A KVM lab whose guest "runs" (the pid file names a live process) and an
/// ssh stub that records its arguments, first on the script's PATH.
struct Lab {
    dir: PathBuf,
    lab: PathBuf,
    _qemu: Sleeper,
}
impl Lab {
    fn new(name: &str) -> Lab {
        let dir = case_dir(name);
        let lab = dir.join("lab");
        fs::create_dir_all(&lab).unwrap();
        keypair(&lab, "id_ed25519");
        let qemu = Sleeper::new();
        fs::write(lab.join("qemu.pid"), qemu.pid()).unwrap();
        // nn-lab.sh puts $HOME/.cargo/bin first on its PATH
        write_exec(
            &dir.join(".cargo/bin/ssh"),
            "#!/bin/bash\nprintf '%s\\n' \"$@\" >> \"$HOME/ssh-calls\"\necho --- >> \"$HOME/ssh-calls\"\nexit 0\n",
        );
        Lab {
            dir,
            lab,
            _qemu: qemu,
        }
    }
    fn run(&self, args: &[&str]) -> Output {
        Command::new("bash")
            .arg(repo_root().join(NN_LAB))
            .args(args)
            .env("HOME", &self.dir)
            .env("NN_LAB_DIR", &self.lab)
            .env_remove("NN_LAB_DISTRO")
            .env_remove("NN_LAB_ACCEL")
            .env_remove("NN_LAB_LOCKDOWN")
            .env_remove("NN_LAB_SSH_PORT")
            .stdin(Stdio::null())
            .output()
            .unwrap()
    }
    fn ssh_calls(&self) -> String {
        fs::read_to_string(self.dir.join("ssh-calls")).unwrap_or_default()
    }
}

/// With no recorded host key nothing connects (it used to connect to
/// whatever answered); with one, the connection carries it, strictly.
/// `down` does not leave a guest it cannot reach to be killed; `destroy`
/// forgets the key with the disk; `status` prints it.
#[test]
fn nn_lab_connects_only_with_the_recorded_host_key() {
    let lab = Lab::new("connect");
    let out = lab.run(&["ssh", "true"]);
    assert!(!out.status.success());
    assert!(
        text(&out).contains("no host key recorded"),
        "{}",
        text(&out)
    );
    assert_eq!(lab.ssh_calls(), "", "ssh ran without a recorded host key");
    let out = lab.run(&["down"]);
    assert!(!out.status.success());
    assert!(text(&out).contains("nothing stopped"), "{}", text(&out));
    assert_eq!(lab.ssh_calls(), "");

    let (_, host) = keypair(&lab.dir, "host");
    fs::write(
        lab.lab.join("known_hosts"),
        format!("nn-lab-ubuntu2404 {host}\n"),
    )
    .unwrap();
    let out = lab.run(&["ssh", "true"]);
    assert!(out.status.success(), "{}", text(&out));
    let calls = lab.ssh_calls();
    let args: Vec<String> = calls
        .lines()
        .take_while(|a| *a != "---")
        .map(str::to_string)
        .collect();
    let guest = args
        .iter()
        .position(|a| a == "nn@127.0.0.1")
        .unwrap_or_else(|| panic!("{args:?}"));
    assert_eq!(&args[guest + 1..], ["true"]);
    assert!(!calls.contains("StrictHostKeyChecking=no"));
    assert!(!calls.contains("UserKnownHostsFile=/dev/null"));
    let opts = &args[..guest];
    let cfg = effective(opts);
    assert!(cfg.lines().any(|l| l == "stricthostkeychecking true"));
    assert!(cfg.lines().any(|l| l
        == format!(
            "userknownhostsfile {}",
            lab.lab.join("known_hosts").display()
        )));

    let out = lab.run(&["status"]);
    assert!(
        text(&out).contains("host key: nn-lab-ubuntu2404 SHA256:"),
        "{}",
        text(&out)
    );

    fs::write(
        lab.lab.join("ssh_host_ed25519_key.pub"),
        format!("{host} x\n"),
    )
    .unwrap();
    fs::remove_file(lab.lab.join("qemu.pid")).unwrap();
    let out = lab.run(&["destroy"]);
    assert!(out.status.success(), "{}", text(&out));
    assert!(!lab.lab.join("known_hosts").exists());
    assert!(!lab.lab.join("ssh_host_ed25519_key.pub").exists());
    assert!(lab.lab.join("id_ed25519").exists(), "the lab key is kept");
}

/// The block that records a guest's host key, with its prelude.
fn host_key_script(lab: &Path, port: &str, pidfile: &Path, body: &str) -> String {
    format!(
        "{}LAB_DIR={lab:?}; ROOT_LAB_DIR=$LAB_DIR; KEY=\"$LAB_DIR/id_ed25519\"; GUEST_NAME=ubuntu2404\n\
         SSH_PORT={port}; ACCEL=kvm; PIDFILE={pidfile:?}; FWD_UNIT=nn-fwd-test; GUEST=nn@127.0.0.1\n\
         {}\n{}\n{body}\n",
        fn_prelude(),
        block(NN_LAB, "ssh-options"),
        block(NN_LAB, "host-key"),
        lab = lab.display().to_string(),
        pidfile = pidfile.display().to_string(),
    )
}

/// A guest whose disk predates injected keys has its key recorded once —
/// only while the forwarded port is served by the guest's own QEMU (its pid
/// file): another process listening there is not asked for a key.
#[test]
fn a_host_key_is_recorded_only_from_the_guests_own_port() {
    if !have("ss") {
        eprintln!("SKIP: no ss on this host");
        return;
    }
    let dir = case_dir("tofu");
    let lab = dir.join("lab");
    fs::create_dir_all(&lab).unwrap();
    let (_, host) = keypair(&dir, "host");
    let listener = Listener::new();
    let other = Sleeper::new();
    let bin = dir.join("bin");
    write_exec(
        &bin.join("ssh-keyscan"),
        "#!/bin/bash\necho \"$*\" >> \"$SCANLOG\"\nprintf '%s\\n' \"${SCAN_REPLY:-}\"\n",
    );
    let path = format!("{}:/usr/sbin:/usr/bin:/sbin:/bin", bin.display());
    let scanlog = dir.join("scans");
    let pidfile = dir.join("qemu.pid");
    let reply = format!("[127.0.0.1]:{} {host}", listener.port);
    let run = |pid: &str, reply: &str| -> (Option<i32>, String) {
        fs::write(&pidfile, pid).unwrap();
        let script = host_key_script(
            &lab,
            &listener.port,
            &pidfile,
            "rc=0; record_existing_host_key || rc=$?; echo \"rc=$rc\"",
        );
        let out = bash(
            &script,
            &[],
            &[
                ("PATH", &path),
                ("SCANLOG", scanlog.to_str().unwrap()),
                ("SCAN_REPLY", reply),
            ],
        );
        (out.status.code(), text(&out))
    };
    // another process's port: not asked, nothing recorded
    let (code, out) = run(&other.pid(), &reply);
    assert_eq!(code, Some(0), "{out}");
    assert!(out.contains("rc=3"), "{out}");
    assert!(!scanlog.exists(), "the port was asked for a key");
    assert!(!lab.join("known_hosts").exists());
    // no ed25519 key in the answer
    let (_, out) = run(&listener.pid(), "[127.0.0.1]:1 ssh-rsa AAAAB3Nza");
    assert!(out.contains("rc=1"), "{out}");
    assert!(!lab.join("known_hosts").exists());
    // the guest's own port
    let (_, out) = run(&listener.pid(), &reply);
    assert!(out.contains("rc=0"), "{out}");
    assert!(out.contains("on first use"), "{out}");
    let kh = lab.join("known_hosts");
    assert_eq!(
        fs::read_to_string(&kh).unwrap(),
        format!("nn-lab-ubuntu2404 {host}\n")
    );
    assert_eq!(
        fs::metadata(&kh).unwrap().permissions().mode() & 0o777,
        0o600
    );
    // a closed port
    let port = listener.port.clone();
    drop(listener);
    fs::remove_file(&kh).unwrap();
    fs::write(&pidfile, other.pid()).unwrap();
    let script = host_key_script(
        &lab,
        &port,
        &pidfile,
        "rc=0; record_existing_host_key || rc=$?; echo \"rc=$rc\"",
    );
    let out = bash(&script, &[], &[("PATH", &path), ("SCAN_REPLY", &reply)]);
    assert!(text(&out).contains("rc=3"), "{}", text(&out));
    assert!(!kh.exists());
}

/// What a connection that fails says: a key that is not the guest's is
/// told apart from a guest that is not up yet (`wait_ssh` keeps waiting
/// for the second, says the first, and `vm_running` under whpx reports
/// it instead of "not running").
#[test]
fn a_wrong_host_key_is_told_apart_from_a_guest_not_up() {
    let dir = case_dir("probe");
    let lab = dir.join("lab");
    fs::create_dir_all(&lab).unwrap();
    let (_, host) = keypair(&dir, "host");
    fs::write(
        lab.join("known_hosts"),
        format!("nn-lab-ubuntu2404 {host}\n"),
    )
    .unwrap();
    let bin = dir.join("bin");
    write_exec(
        &bin.join("ssh"),
        "#!/bin/bash\nprintf '%s\\n' \"$SSH_SAYS\" >&2\nexit \"$SSH_RC\"\n",
    );
    let path = format!("{}:/usr/sbin:/usr/bin:/sbin:/bin", bin.display());
    for (says, rc, want) in [
        ("", "0", "probe=0"),
        ("ssh: connect to host 127.0.0.1 port 2322: Connection refused", "255", "probe=1"),
        ("kex_exchange_identification: read: Connection reset by peer", "255", "probe=1"),
        ("Host key verification failed.", "255", "probe=2"),
        (
            "Unable to negotiate with 127.0.0.1 port 2322: no matching host key type found. Their offer: rsa-sha2-512",
            "255",
            "probe=2",
        ),
    ] {
        let script = host_key_script(
            &lab,
            "2322",
            &dir.join("none.pid"),
            "p=0; guest_probe || p=$?; echo \"probe=$p\"",
        );
        let out = bash(&script, &[], &[("PATH", &path), ("SSH_SAYS", says), ("SSH_RC", rc)]);
        assert!(text(&out).contains(want), "{says:?}: {}", text(&out));
    }
}

/// A new instance's key is in known_hosts before its first boot; a lost
/// known_hosts is rebuilt from the key in the guest's user-data, and only
/// from it.
#[test]
fn a_new_guest_is_known_before_its_first_boot() {
    let dir = case_dir("injected");
    let lab = dir.join("lab");
    fs::create_dir_all(&lab).unwrap();
    keypair(&lab, "id_ed25519");
    let tmpl = repo_root().join("deploy/lab/user-data.tmpl");
    let script = host_key_script(
        &lab,
        "2322",
        &dir.join("none.pid"),
        &format!(
            "{}\nUSER_DATA_TMPL={tmpl:?}; LOCKDOWN=\nrender_user_data \"$LAB_DIR/user-data\"\nrecord_injected_host_key\n\
             cp \"$KNOWN_HOSTS\" \"$LAB_DIR/first\"; rm \"$KNOWN_HOSTS\"\n\
             known_host_from_seed && cmp \"$KNOWN_HOSTS\" \"$LAB_DIR/first\" && echo SEED-OK\n\
             rm \"$KNOWN_HOSTS\"; sed -i '/ed25519_public/d' \"$LAB_DIR/user-data\"\n\
             if known_host_from_seed; then echo SEED-WRONG; else echo SEED-REFUSED; fi\n",
            block(NN_LAB, "render-user-data"),
            tmpl = tmpl.display().to_string(),
        ),
    );
    let out = bash(&script, &[], &[]);
    let t = text(&out);
    assert!(out.status.success(), "{t}");
    assert!(t.contains("SEED-OK") && t.contains("SEED-REFUSED"), "{t}");
    let pub_line = fs::read_to_string(lab.join("ssh_host_ed25519_key.pub")).unwrap();
    let public: Vec<&str> = pub_line.split_whitespace().take(2).collect();
    assert_eq!(
        fs::read_to_string(lab.join("first")).unwrap(),
        format!("nn-lab-ubuntu2404 {}\n", public.join(" "))
    );
    assert!(!lab.join("known_hosts").exists());
}

/// No connection to a guest outside the four helpers, and none with host
/// key checking off.
#[test]
fn nn_lab_has_no_unchecked_guest_connection() {
    let text = read(NN_LAB);
    for (n, l) in text.lines().enumerate() {
        let code = l.trim_start();
        if code.starts_with('#') {
            continue;
        }
        assert!(
            !code.contains("StrictHostKeyChecking=no")
                && !code.contains("UserKnownHostsFile=/dev/null"),
            "{NN_LAB}:{}: {l}",
            n + 1
        );
        assert!(!code.contains("SSH_OPTS[*]"), "{NN_LAB}:{}: {l}", n + 1);
        for tool in ["ssh ", "scp ", "rsync "] {
            let direct = code.starts_with(tool)
                || code.contains(&format!("; {tool}"))
                || code.contains(&format!("&& {tool}"));
            let helper = code.starts_with("vssh() {")
                || code.starts_with("vrsync() {")
                || code.starts_with("vscp() {");
            assert!(
                !direct || helper,
                "{NN_LAB}:{}: a direct `{tool}`: {l}",
                n + 1
            );
        }
    }
}

// ── LAB-022: ~/.aws (open-sensor-check.sh) ──────────────────────────────

/// The check wrote `~/.aws/credentials` and `rm -rf`-ed `~/.aws` on any
/// host. Off a lab guest, without NN_TEST_DISPOSABLE_HOST=1, it stops
/// before running anything (stubs on PATH record any call).
#[test]
fn open_sensor_check_refuses_a_host_that_is_not_a_lab_guest() {
    if Path::new("/var/lib/nn-lab-provisioned").exists() {
        eprintln!("SKIP: this host is an nn-lab guest");
        return;
    }
    let dir = case_dir("open-sensor-refuse");
    let bin = dir.join("bin");
    for tool in [
        "sudo",
        "systemctl",
        "journalctl",
        "getent",
        "install",
        "tee",
        "mv",
        "rm",
    ] {
        write_exec(
            &bin.join(tool),
            &format!("#!/bin/bash\necho {tool} >> \"$CALLS\"\n"),
        );
    }
    // the stubs only: a check that got past its guard would find nothing
    // else to run
    let path = bin.display().to_string();
    let calls = dir.join("calls");
    for opt_in in [None, Some("0"), Some("yes"), Some("")] {
        let mut cmd = Command::new("/bin/bash");
        cmd.arg(repo_root().join(OPEN_SENSOR))
            .env("PATH", &path)
            .env("CALLS", &calls)
            .env("HOME", &dir)
            .env_remove("NN_TEST_DISPOSABLE_HOST");
        if let Some(v) = opt_in {
            cmd.env("NN_TEST_DISPOSABLE_HOST", v);
        }
        let out = cmd.output().unwrap();
        assert_eq!(out.status.code(), Some(2), "{opt_in:?}: {}", text(&out));
        assert!(text(&out).contains("refusing to run"), "{}", text(&out));
        assert!(
            !calls.exists(),
            "{opt_in:?}: ran {:?}",
            fs::read_to_string(&calls)
        );
    }
}

/// How a run of the fixture ends: the end of step 2, an error exit, or a
/// signal.
const ENDINGS: [(&str, &str, i32); 5] = [
    ("restore", "aws_fixture_restore || exit 9; exit 0", 0),
    ("error", "exit 1", 1),
    ("ctrl-c", "kill -INT $$; sleep 5; exit 0", 130),
    ("term", "kill -TERM $$; sleep 5; exit 0", 143),
    ("hup", "kill -HUP $$; sleep 5; exit 0", 129),
];

/// The fixture block with `sudo` as a pass-through, set up in `$1`; `$2`
/// is how the run ends. Exit 7: setup refused, 8: no fixture written.
fn aws_script(ending: &str) -> String {
    format!(
        "set -u\nsudo() {{ \"$@\"; }}\n{}\nH=$1\n\
         aws_fixture_setup \"$H\" \"$(id -un)\" || exit 7\n\
         grep -qx 'aws_access_key_id = NNOPENSENSOR' \"$H/.aws/credentials\" || exit 8\n\
         if [[ -e $H/real-aws/credentials ]]; then cmp -s \"$H/real-aws/credentials\" \"$H/sentinel\" || exit 10; fi\n\
         {ending}\n",
        block(OPEN_SENSOR, "aws-fixture")
    )
}

/// A sentinel `~/.aws` (a directory with credentials and config, or a link
/// to one elsewhere, or none) is the same after the check, whichever way
/// the run ends; the fixture never goes through a link.
#[test]
fn the_aws_fixture_puts_back_what_it_found() {
    let sentinel =
        "[default]\naws_access_key_id = AKIAOPERATORSREAL\naws_secret_access_key = keep-me\n";
    for (ending, body, code) in ENDINGS {
        for layout in ["dir", "link", "none"] {
            let home = case_dir(&format!("aws-{ending}-{layout}"));
            fs::write(home.join("sentinel"), sentinel).unwrap();
            let aws = home.join(".aws");
            match layout {
                "dir" => {
                    fs::create_dir(&aws).unwrap();
                    fs::write(aws.join("credentials"), sentinel).unwrap();
                    fs::write(aws.join("config"), "[default]\nregion = eu-south-1\n").unwrap();
                    fs::set_permissions(&aws, fs::Permissions::from_mode(0o750)).unwrap();
                }
                "link" => {
                    fs::create_dir(home.join("real-aws")).unwrap();
                    fs::write(home.join("real-aws/credentials"), sentinel).unwrap();
                    std::os::unix::fs::symlink("real-aws", &aws).unwrap();
                }
                _ => {}
            }
            let out = bash(&aws_script(body), &[home.to_str().unwrap()], &[]);
            let what = format!("{ending}/{layout}: {}", text(&out));
            assert_eq!(out.status.code(), Some(code), "{what}");
            assert!(!home.join(".aws.nn-open-sensor").exists(), "{what}");
            match layout {
                "dir" => {
                    assert_eq!(
                        fs::read_to_string(aws.join("credentials")).unwrap(),
                        sentinel,
                        "{what}"
                    );
                    assert!(aws.join("config").exists(), "{what}");
                    let mode = fs::symlink_metadata(&aws).unwrap().permissions().mode();
                    assert_eq!(mode & 0o777, 0o750, "{what}");
                }
                "link" => {
                    assert_eq!(
                        fs::read_link(&aws).unwrap(),
                        Path::new("real-aws"),
                        "{what}"
                    );
                    assert_eq!(
                        fs::read_to_string(home.join("real-aws/credentials")).unwrap(),
                        sentinel,
                        "{what}"
                    );
                }
                _ => assert!(fs::symlink_metadata(&aws).is_err(), "{what}"),
            }
        }
    }
}

/// A `~/.aws.nn-open-sensor` left by a run that could not put `~/.aws`
/// back stops the check before it moves anything; a file the check did not
/// write keeps the fixture's directory, and the saved one waits, reported.
#[test]
fn the_aws_fixture_never_overwrites_a_saved_copy() {
    let sentinel = "[default]\naws_access_key_id = AKIAOPERATORSREAL\n";
    let home = case_dir("aws-leftover");
    fs::create_dir(home.join(".aws")).unwrap();
    fs::write(home.join(".aws/credentials"), sentinel).unwrap();
    fs::create_dir(home.join(".aws.nn-open-sensor")).unwrap();
    fs::write(home.join(".aws.nn-open-sensor/credentials"), "older\n").unwrap();
    let out = bash(&aws_script("exit 0"), &[home.to_str().unwrap()], &[]);
    assert_eq!(out.status.code(), Some(7), "{}", text(&out));
    assert!(text(&out).contains(".aws.nn-open-sensor exists"));
    assert_eq!(
        fs::read_to_string(home.join(".aws/credentials")).unwrap(),
        sentinel
    );
    assert_eq!(
        fs::read_to_string(home.join(".aws.nn-open-sensor/credentials")).unwrap(),
        "older\n"
    );

    let home = case_dir("aws-extra");
    fs::create_dir(home.join(".aws")).unwrap();
    fs::write(home.join(".aws/credentials"), sentinel).unwrap();
    let out = bash(
        &aws_script(
            "echo other > \"$H/.aws/other\"; rc=0; aws_fixture_restore || rc=$?; echo \"rc=$rc\"; exit 0",
        ),
        &[home.to_str().unwrap()],
        &[],
    );
    let t = text(&out);
    assert!(t.contains("rc=1") && t.contains("left in place"), "{t}");
    assert_eq!(
        fs::read_to_string(home.join(".aws/other")).unwrap(),
        "other\n"
    );
    assert!(
        !home.join(".aws/credentials").exists(),
        "the fixture is removed"
    );
    assert_eq!(
        fs::read_to_string(home.join(".aws.nn-open-sensor/credentials")).unwrap(),
        sentinel
    );
}

/// The check calls the fixture block and no longer removes `~/.aws` itself.
#[test]
fn open_sensor_check_uses_the_fixture_block() {
    let text = read(OPEN_SENSOR);
    let code: Vec<&str> = text
        .lines()
        .filter(|l| !l.trim_start().starts_with('#'))
        .collect();
    assert!(!code
        .iter()
        .any(|l| l.contains("rm -rf") && l.contains(".aws")));
    assert!(code
        .iter()
        .any(|l| l.contains("aws_fixture_setup \"$H\" \"$U\"")));
    assert!(code.iter().any(|l| l.starts_with("aws_fixture_restore ||")));
    let guard = text.find("if ! aws_fixture_allowed; then").unwrap();
    let first_cmd = text.find("DET=").unwrap();
    assert!(
        guard < first_cmd,
        "the guard must come before anything runs"
    );
}

// ── LAB-019: the range teardown (07_teardown.sh) ────────────────────────

/// A VirtualBox host: a `VBoxManage` stub that answers from files and logs
/// every call.
struct VBox {
    dir: PathBuf,
}
impl VBox {
    fn new(name: &str, target_disk: &str) -> VBox {
        let dir = case_dir(name);
        let state = dir.join("state");
        fs::create_dir_all(&state).unwrap();
        fs::write(
            state.join("kalidev.info"),
            "name=\"kalidev\"\nCfgFile=\"/vms/kalidev/kalidev.vbox\"\n\
             \"SATA-0-0\"=\"/vms/kalidev/kalidev.vdi\"\n\"SATA-ImageUUID-0-0\"=\"0f1e2d3c-1111-2222-3333-444455556666\"\n\
             \"IDE-0-0\"=\"/isos/kali-2025.iso\"\n\"IDE-IsEjected-0-0\"=\"off\"\n\"IDE-0-1\"=\"none\"\n",
        )
        .unwrap();
        fs::write(
            state.join("northnarrowdev.info"),
            format!(
                "name=\"northnarrowdev\"\nCfgFile=\"/vms/northnarrowdev/northnarrowdev.vbox\"\n\
                 \"SATA Controller-0-0\"=\"{target_disk}\"\n"
            ),
        )
        .unwrap();
        fs::write(
            state.join("disks"),
            format!("/vms/kalidev/kalidev.vdi\n{target_disk}\n"),
        )
        .unwrap();
        fs::write(state.join("running"), "\"kalidev\" {0f1e}\n").unwrap();
        write_exec(
            &dir.join("bin/VBoxManage"),
            "#!/bin/bash\necho \"$*\" >> \"$VBOX_LOG\"\ncase \"$1\" in\n\
             showvminfo) [ -f \"$VBOX_STATE/$2.info\" ] || exit 1; [ \"${3:-}\" = --machinereadable ] && cat \"$VBOX_STATE/$2.info\"; exit 0 ;;\n\
             list) cat \"$VBOX_STATE/running\" ;;\n\
             showmediuminfo) grep -qxF \"$3\" \"$VBOX_STATE/disks\" ;;\n\
             *) exit 0 ;;\nesac\n",
        );
        VBox { dir }
    }
    fn run(&self, keep: Option<&str>, force: bool, stdin: &str) -> (Option<i32>, String, String) {
        let mut cmd = Command::new("bash");
        cmd.arg(repo_root().join(TEARDOWN))
            .env(
                "PATH",
                format!(
                    "{}:{}",
                    self.dir.join("bin").display(),
                    std::env::var("PATH").unwrap()
                ),
            )
            .env("VBOX_LOG", self.dir.join("log"))
            .env("VBOX_STATE", self.dir.join("state"))
            .env_remove("KEEP_DISKS")
            .env_remove("FORCE")
            .env_remove("ATTACKER_VM")
            .env_remove("TARGET_VM")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        if let Some(k) = keep {
            cmd.env("KEEP_DISKS", k);
        }
        if force {
            cmd.env("FORCE", "1");
        }
        let mut child = cmd.spawn().unwrap();
        use std::io::Write;
        child
            .stdin
            .take()
            .unwrap()
            .write_all(stdin.as_bytes())
            .unwrap();
        let out = child.wait_with_output().unwrap();
        let log = fs::read_to_string(self.dir.join("log")).unwrap_or_default();
        let _ = fs::remove_file(self.dir.join("log"));
        (out.status.code(), text(&out), log)
    }
}

fn acted(log: &str) -> Vec<&str> {
    log.lines()
        .filter(|l| l.starts_with("controlvm") || l.starts_with("unregistervm"))
        .collect()
}

/// `KEEP_DISKS=0` printed "disks kept0" and deleted them, FORCE=1 printed
/// nothing, and any other value deleted too. The line always printed, the
/// prompt and the branch now say the same thing, and only 0 or 1 is taken.
#[test]
fn teardown_says_what_it_does_and_does_it() {
    let vbox = VBox::new("teardown", "/vms/northnarrowdev/northnarrowdev.vdi");
    for keep in [None, Some("0")] {
        let (code, out, log) = vbox.run(keep, true, "");
        assert_eq!(code, Some(0), "{keep:?}: {out}");
        assert!(
            out.contains("disks DELETED") && !out.contains("kept"),
            "{keep:?}: {out}"
        );
        assert_eq!(
            acted(&log),
            [
                "controlvm kalidev poweroff",
                "unregistervm kalidev --delete",
                "unregistervm northnarrowdev --delete"
            ],
            "{keep:?}"
        );
    }
    let (code, out, log) = vbox.run(Some("1"), true, "");
    assert_eq!(code, Some(0), "{out}");
    assert!(out.contains("disks KEPT"), "{out}");
    assert_eq!(
        acted(&log),
        [
            "controlvm kalidev poweroff",
            "unregistervm kalidev",
            "unregistervm northnarrowdev"
        ]
    );
    for bad in ["yes", "true", "2", "01"] {
        let (code, out, log) = vbox.run(Some(bad), true, "");
        assert_ne!(code, Some(0), "KEEP_DISKS={bad:?}: {out}");
        assert!(out.contains("KEEP_DISKS must be 0"), "{out}");
        assert!(acted(&log).is_empty(), "KEEP_DISKS={bad:?}: {log}");
    }
    // the prompt (no FORCE): what it asks is what it would do
    let (code, out, log) = vbox.run(None, false, "n\n");
    assert_ne!(code, Some(0));
    assert!(
        out.contains("(disks DELETED)? [y/N]") && out.contains("aborted"),
        "{out}"
    );
    assert!(acted(&log).is_empty());
    let (code, out, log) = vbox.run(Some("1"), false, "y\n");
    assert_eq!(code, Some(0), "{out}");
    assert!(out.contains("(disks KEPT)? [y/N]"), "{out}");
    assert_eq!(acted(&log).len(), 3);
}

/// `--delete` deletes every hard disk of the VM. A disk attached from
/// outside the VM's folder stops the teardown before anything is powered
/// off (an ISO outside it does not: `--delete` leaves DVD images); with
/// KEEP_DISKS=1 nothing is deleted, so it goes on.
#[test]
fn teardown_deletes_no_disk_outside_the_vm_folder() {
    for disk in [
        "/data/shared/base.vdi",
        "/vms/northnarrowdev/../kalidev/kalidev.vdi",
    ] {
        let vbox = VBox::new("teardown-outside", disk);
        let (code, out, log) = vbox.run(None, true, "");
        assert_ne!(code, Some(0), "{disk}: {out}");
        assert!(
            out.contains(disk) && out.contains("refusing to delete 'northnarrowdev'"),
            "{out}"
        );
        assert!(acted(&log).is_empty(), "{disk}: {log}");
        let (code, out, log) = vbox.run(Some("1"), true, "");
        assert_eq!(code, Some(0), "{out}");
        assert_eq!(acted(&log).len(), 3, "{log}");
    }
}

// ── LAB-027: the range bootstrap (bootstrap-target-prod.sh) ─────────────

/// A git repository at `repo`, one commit, umask 022.
fn git_repo(repo: &Path) -> String {
    let script = "set -euo pipefail; umask 022; mkdir -p \"$1\"; cd \"$1\"\n\
                  git init -q .; git config user.email t@example.invalid; git config user.name t\n\
                  echo a > a.txt; mkdir -p sub; echo b > sub/b.txt; printf 'config.toml\\n/target/\\n' > .gitignore\n\
                  git add -A; git commit -qm one; git rev-parse HEAD\n";
    let out = bash(script, &[repo.to_str().unwrap()], &[]);
    assert!(out.status.success(), "{}", text(&out));
    String::from_utf8_lossy(&out.stdout).trim().to_string()
}

fn tree_check(repo: &Path, env: &[(&str, &str)]) -> (bool, String) {
    let script = format!(
        "set -euo pipefail\nwarn() {{ echo \"warn: $*\" >&2; }}\nlog() {{ :; }}\ndie() {{ echo \"die: $*\" >&2; exit 1; }}\n\
         as_build_user() {{ bash -c \"$1\"; }}\n{}\n\
         if range_tree_check \"$1\" \"$(id -un)\"; then echo \"OK state=$TREE_STATE head=$TREE_HEAD\"; else echo REFUSED; fi\n",
        block(BOOTSTRAP, "range-tree")
    );
    let out = bash(&script, &[repo.to_str().unwrap()], env);
    let t = text(&out);
    assert!(out.status.success(), "{t}");
    (t.contains("OK state="), t)
}

/// The bootstrap built whatever the tree held and installed it as root.
/// It now refuses, before anything is stopped, a tree with uncommitted or
/// untracked paths (unless NN_ALLOW_DIRTY_TREE=1, which is recorded), a
/// HEAD other than NN_EXPECT_COMMIT, a path writable by others, and cargo
/// configuration git does not see (ignored in the tree, or in a parent).
#[test]
fn range_bootstrap_refuses_a_tree_it_cannot_vouch_for() {
    let guard = outside_dir("tree");
    let base = guard.0.clone();
    let repo = base.join("repo");
    let first = git_repo(&repo);
    let (ok, t) = tree_check(&repo, &[]);
    assert!(ok, "{t}");
    assert!(t.contains(&format!("OK state=clean head={first}")), "{t}");

    fs::write(repo.join("a.txt"), "changed\n").unwrap();
    let (ok, t) = tree_check(&repo, &[]);
    assert!(!ok && t.contains("uncommitted"), "{t}");
    let (ok, t) = tree_check(&repo, &[("NN_ALLOW_DIRTY_TREE", "1")]);
    assert!(
        ok && t.contains("state=dirty, allowed by NN_ALLOW_DIRTY_TREE=1"),
        "{t}"
    );
    fs::write(repo.join("a.txt"), "a\n").unwrap();

    fs::write(repo.join("untracked.rs"), "fn main() {}\n").unwrap();
    let (ok, t) = tree_check(&repo, &[]);
    assert!(!ok && t.contains("untracked.rs"), "{t}");
    fs::remove_file(repo.join("untracked.rs")).unwrap();

    // NN_EXPECT_COMMIT
    let out = bash(
        "set -e; cd \"$1\"; echo c > c.txt; git add c.txt; git commit -qm two; git rev-parse --short HEAD",
        &[repo.to_str().unwrap()],
        &[],
    );
    let second = String::from_utf8_lossy(&out.stdout).trim().to_string();
    let (ok, t) = tree_check(&repo, &[("NN_EXPECT_COMMIT", &second)]);
    assert!(ok, "{t}");
    let (ok, t) = tree_check(&repo, &[("NN_EXPECT_COMMIT", &first)]);
    assert!(!ok && t.contains("NN_EXPECT_COMMIT is"), "{t}");
    let (ok, t) = tree_check(&repo, &[("NN_EXPECT_COMMIT", "no-such-ref")]);
    assert!(!ok && t.contains("names no commit"), "{t}");

    // writable by others
    let sub = repo.join("sub");
    fs::set_permissions(&sub, fs::Permissions::from_mode(0o757)).unwrap();
    let (ok, t) = tree_check(&repo, &[]);
    assert!(!ok && t.contains("writable by others"), "{t}");
    fs::set_permissions(&sub, fs::Permissions::from_mode(0o755)).unwrap();
    fs::set_permissions(repo.join("sub/b.txt"), fs::Permissions::from_mode(0o646)).unwrap();
    let (ok, t) = tree_check(&repo, &[]);
    assert!(!ok && t.contains("b.txt"), "{t}");
    fs::set_permissions(repo.join("sub/b.txt"), fs::Permissions::from_mode(0o644)).unwrap();

    // cargo configuration git ignores
    fs::create_dir_all(repo.join("sub/.cargo")).unwrap();
    fs::write(
        repo.join("sub/.cargo/config.toml"),
        "[build]\nrustflags = []\n",
    )
    .unwrap();
    let (ok, t) = tree_check(&repo, &[]);
    assert!(!ok && t.contains("cargo configuration git ignores"), "{t}");
    fs::remove_dir_all(repo.join("sub/.cargo")).unwrap();
    fs::create_dir_all(base.join(".cargo")).unwrap();
    fs::write(base.join(".cargo/config.toml"), "[build]\n").unwrap();
    let (ok, t) = tree_check(&repo, &[]);
    assert!(!ok && t.contains("cargo would read it"), "{t}");
    fs::remove_dir_all(base.join(".cargo")).unwrap();

    let (ok, t) = tree_check(&repo, &[]);
    assert!(ok, "{t}");
}

/// The check runs before step 1 stops anything; the build runs without
/// login profiles; the installed binaries are checked against the build
/// and recorded with the commit.
#[test]
fn range_bootstrap_checks_first_and_records_what_it_installed() {
    let text = read(BOOTSTRAP);
    let code: Vec<&str> = text
        .lines()
        .filter(|l| !l.trim_start().starts_with('#'))
        .collect();
    assert!(
        !code.iter().any(|l| l.contains("bash -lc")),
        "login profiles"
    );
    assert!(code
        .iter()
        .any(|l| l.contains("env -i HOME=\"$BUILD_HOME\"")));
    let check = text
        .find("range_tree_check \"$NN_REPO_DIR\" \"$BUILD_USER\"")
        .expect("the tree check is called");
    let step1 = text.find("# ── 1. stop").unwrap();
    let build = text.find("cargo xtask build --release\"").unwrap();
    let install = text.find("bash deploy/install.sh --source-tree").unwrap();
    let prov = text
        .find("install -m 0644 -o root -g root \"$prov_tmp\" \"$RANGE_PROVENANCE\"")
        .expect("the provenance file is written");
    let health = text.find("# ── 8. HEALTH CHECK").unwrap();
    assert!(check < step1 && step1 < build && build < install && install < prov && prov < health);
    let record = &text[install..prov];
    for want in [
        "for b in northnarrow-agent northnarrow-watchdog nn-admin; do",
        "is not the binary built from",
        "echo \"commit: $TREE_HEAD\"",
        "echo \"tree: $TREE_STATE\"",
        "echo \"$inst  $NN_BIN_DIR/$b\"",
    ] {
        assert!(record.contains(want), "no `{want}` in the provenance step");
    }
    assert!(read("deploy/adversarial/00_config.sh")
        .contains(": \"${RANGE_PROVENANCE:=/root/range-provenance.txt}\""));
}
